const p = $('When Executed by Another Workflow').first().json;
const rows = $input.all().map(i => i.json);

const norm = v => (v ?? '').toString().trim().toLowerCase();
const EMPTY = ['', 'null', 'none', 'any', 'all', 'n/a', 'undefined'];
const terms = v => norm(v).split(/[,;|]/).map(s => s.trim()).filter(s => s && !EMPTY.includes(s));

const GENERIC = ['production','production car','production cars','car','cars','vehicle',
  'vehicles','fastest','road legal','street legal','street-legal','nurburgring','nürburgring'];
const alias = { ev:'electric', evs:'electric', electrics:'electric', 'electric car':'electric',
  'electric cars':'electric', 'sports car':'sportscar', 'sports cars':'sportscar',
  sportscars:'sportscar', 'super car':'supercar', 'super cars':'supercar', supercars:'supercar',
  hypercars:'hypercar', sedans:'sedan', suvs:'suv', hybrids:'hybrid', 'track cars':'track car',
  prototypes:'prototype' };

let typeTerms = [...terms(p.category), ...terms(p.powertrain), ...terms(p.list)]
  .map(t => alias[t] ?? t).filter(t => !GENERIC.includes(t));
const wantProto = typeTerms.includes('prototype');
typeTerms = typeTerms.filter(t => t !== 'prototype');
// Country / region -> brands (so "Japanese" works even though the table has no country column)
const COUNTRIES = {};
const addGroup = (names, brands) => names.forEach(n => COUNTRIES[n] = brands);
addGroup(['japanese', 'japan'], ['honda', 'toyota', 'lexus', 'nissan', 'subaru', 'mazda', 'mitsubishi', 'acura', 'infiniti']);
addGroup(['italian', 'italy'], ['ferrari', 'lamborghini', 'maserati', 'pagani', 'alfa romeo']);
addGroup(['german', 'germany'], ['porsche', 'mercedes', 'bmw', 'audi', 'volkswagen', 'alpina', 'ruf', 'gumpert', 'opel']);
addGroup(['american', 'usa', 'us', 'america'], ['chevrolet', 'ford', 'dodge', 'tesla', 'cadillac']);
addGroup(['british', 'uk', 'english', 'britain'], ['mclaren', 'aston martin', 'jaguar', 'lotus', 'radical', 'mini']);
addGroup(['korean', 'south korean', 'korea'], ['hyundai', 'kia', 'genesis']);
addGroup(['chinese', 'china'], ['xiaomi', 'yangwang', 'lynk', 'nio', 'byd']);
addGroup(['french', 'france'], ['renault', 'bugatti', 'alpine', 'peugeot']);
addGroup(['swedish', 'sweden'], ['koenigsegg', 'volvo', 'polestar']);

const rawCarTerms = terms(p.car_contains).filter(t => !GENERIC.includes(t));
const expanded = rawCarTerms.some(t => COUNTRIES[t]);
const carTerms = rawCarTerms.flatMap(t => COUNTRIES[t] ?? [t]);
const driverTerms = terms(p.driver);
const yearTerms = terms(p.year);

const m = String(p.limit ?? '').match(/\d+/);
const limit = Math.min(Math.max(m ? parseInt(m[0]) : 5, 1), 25);
const slowest = norm(p.order).includes('slow');

let out = rows.filter(r => norm(r.track) === 'nordschleife' && norm(r.list) !== 'autonomous');
const isProto = r => norm(r.list) === 'prototype';
if (!wantProto) out = out.filter(r => !isProto(r));
if (wantProto && !typeTerms.length) out = out.filter(isProto);

if (carTerms.length)    out = out.filter(r => carTerms.some(t => norm(r.car).includes(t)));
if (driverTerms.length) out = out.filter(r => driverTerms.some(t => norm(r.driver).includes(t)));
let yearNote = '';
if (yearTerms.length) {
  const y = out.filter(r => yearTerms.includes(norm(r.year)));
  const otherFilters = carTerms.length || driverTerms.length || typeTerms.length;
  if (y.length || !otherFilters) out = y;   // year-only questions stay strict
  else yearNote = 'The year filter (' + yearTerms.join(', ') + ') matched nothing for these cars, so it was ignored.';
}

// Type filter is "soft": if it would leave nothing, ignore it
let typeNote = '';
if (typeTerms.length) {
  const typed = out.filter(r => typeTerms.some(t => [r.category, r.powertrain, r.list].map(norm).includes(t)));
  if (typed.length) out = typed;
  else typeNote = 'The type filter (' + typeTerms.join(', ') + ') matched nothing, so it was ignored.';
}

out.sort((a, b) => slowest
  ? Number(b.lap_seconds) - Number(a.lap_seconds)
  : Number(a.lap_seconds) - Number(b.lap_seconds));

if (norm(p.count_by) === 'driver') {
  const counts = {};
  for (const r of out) {
    const d = (r.driver || '').trim();
    if (d && d !== '—') counts[d] = (counts[d] || 0) + 1;
  }
  const ranking = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, limit)
    .map(([driver, records]) => ({ driver, records }));
  return [{ json: { total_matches: out.length, driver_ranking: ranking,
    note: 'Counts rows in the dataset. Rows with no driver listed are skipped.' } }];
}

// Fastest row for each car searched (for "is X faster than Y?" questions)
const byTerm = (carTerms.length > 1  && !expanded) ? carTerms.map(t => {
  const best = out.find(r => norm(r.car).includes(t));
  return best
    ? { search: t, car: best.car, lap_time: best.lap_time,
        lap_seconds: Number(best.lap_seconds), distance_km: best.distance_km }
    : { search: t, car: null };
}) : null;

let verdict = '';
if (byTerm && new Set(byTerm.filter(x => x.car).map(x => x.car)).size < 2)
  verdict = 'The search words matched only one car. Search again with two different car names.';
if (byTerm) {
  const found = byTerm.filter(x => x.car).sort((a, b) => a.lap_seconds - b.lap_seconds);
  if (found.length > 1 && found[0].car !== found[1].car) {
    const gap = (found[1].lap_seconds - found[0].lap_seconds).toFixed(2);
    verdict = `${found[0].car} (${found[0].lap_time}) is FASTER than ${found[1].car} (${found[1].lap_time}) by ${gap} seconds. Lower lap_seconds is faster.`;
  }
}

return [{ json: {
  total_matches: out.length,
  ...(verdict ? { verdict, best_per_car_term: byTerm } : {}),
  note: (typeNote + ' ' + yearNote + ' ' + (out.length
    ? 'distance_km is 20.832 (full lap), 20.6 (shortened) or unspecified. Times on different distances are not directly comparable.'
    : 'No rows matched these filters.')).trim(),
  results: out.slice(0, limit).map((r, i) => ({
    position: i + 1, car: r.car, category: r.category, powertrain: r.powertrain,
    driver: r.driver, date: r.date, year: r.year, lap_time: r.lap_time,
    lap_seconds: r.lap_seconds, distance_km: r.distance_km, list: r.list, notes: r.notes
  }))
}}];
